def median_of_stream(nums: list) -> list:
    lower_half = []  # max-heap (using negative values to simulate max-heap with heapq)
    upper_half = []  # min-heap
    medians = []

    for num in nums:
        if not lower_half or num <= -lower_half[0]:
            heapq.heappush(lower_half, -num)
        else:
            heapq.heappush(upper_half, num)

        # Rebalance heaps if necessary
        if len(lower_half) > len(upper_half) + 1:
            heapq.heappush(upper_half, -heapq.heappop(lower_half))
        elif len(upper_half) > len(lower_half):
            heapq.heappush(lower_half, -heapq.heappop(upper_half))

        # Calculate median
        if len(lower_half) == len(upper_half):
            median = (-lower_half[0] + upper_half[0]) / 2
        else:
            median = -lower_half[0]

        medians.append(median)

    return medians

