        visited[node] = True
        nonlocal time
        discovery_time[node] = low_time[node] = time
        time += 1
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, discovery_time, low_time, time, visited, bridges, graph)
                low_time[node] = min(low_time[node], low_time[neighbor])
                if low_time[neighbor] > discovery_time[node]:
                    bridges.append((node, neighbor))
            else:
                low_time[node] = min(low_time[node], discovery_time[neighbor])

    bridges = []
    visited = [False] * n
    discovery_time = [0] * n
    low_time = [0] * n
    graph = {i: [] for i in range(n)}
    for conn in connections:
        graph[conn[0]].append(conn[1])
        graph[conn[1]].append(conn[0])

    for i in range(n):
        if not visited[i]:
            dfs(i, discovery_time, low_time, 0, visited, bridges, graph)

    return bridges

