def full_justify(words: list, max_width: int) -> list:
    def justify_line(line: list, width: int) -> str:
        if len(line) == 1:
            return line[0] + ' ' * (width - len(line[0]))
        spaces_needed = width - sum(len(word) for word in line)
        extra_spaces = spaces_needed % (len(line) - 1)
        space_size = spaces_needed // (len(line) - 1)
        return (' ' * (space_size + (1 if i <= extra_spaces else 0)).join(line) for i in range(len(line)))

    lines, current_line, current_length = [], [], 0

    for word in words:
        if current_length + len(word) + len(current_line) > max_width:
            lines.append(justify_line(current_line, max_width))
            current_line, current_length = [], 0
        current_line.append(word)
        current_length += len(word)

    if current_line:
        lines.append(' '.join(current_line).ljust(max_width))

    return [''.join(line) for line in lines]

